/// <summary>
/// The <c>AVAPriceIncreaseContract</c> class is the data contract class for <c>AVAPriceIncrease</c>
/// </summary>
[
    DataContractAttribute,
    SysOperationContractProcessingAttribute(classStr(AVAPriceIncreaseUIBuilder)),
    SysOperationGroupAttribute('PriceDiscGroup', literalStr("@NDX:NXAPriceIncreaseCreateJournals"), '2', FormArrangeMethod::Vertical)
]
class AVAPriceIncreaseContract implements   SysOperationValidatable,
                                            SysOperationInitializable
{
    Args                                    frmArgs;
    AVAPriceIncreaseSet                     frmAVAPriceIncreaseSet;
    PriceGroupId                            frmPriceGroupId;
    PriceDiscModule                         frmPriceDiscModule;
    PriceGroupType                          frmPriceGroupType;
    AVAPriceIncreasePriceDiscGroup          frmAVAPriceIncreasePriceDiscGroup;

    List                                    frmRecIdList;

    boolean                                 lJobMode;

}

Method.Source:
/// <summary>
///    AVA <c>validate</c> method.
/// </summary>
/// <returns>
///    Value <c>boolean</c> as result
/// </returns>
public boolean validate()
{
    boolean retVal;

    retVal = true;

    return retVal;
}

/// <summary>
///    AVA <c>initialize</c> method.
/// </summary>
public void initialize()
{
    Common                          locCommon;
    AVAPriceIncreasePriceDiscGroup  locAVAPriceIncreasePriceDiscGroup;

    if (frmArgs && frmArgs.record())
    {
        locCommon = frmArgs.record();
        if(     locCommon.RecId
            &&  locCommon.TableId == tableNum(AVAPriceIncreasePriceDiscGroup))
        {
            locAVAPriceIncreasePriceDiscGroup = locCommon;

            frmAVAPriceIncreaseSet  = locAVAPriceIncreasePriceDiscGroup.PriceIncreaseSet;
            frmPriceGroupId         = locAVAPriceIncreasePriceDiscGroup.GroupId ;
            frmPriceDiscModule      = locAVAPriceIncreasePriceDiscGroup.Module;
            frmPriceGroupType       = locAVAPriceIncreasePriceDiscGroup.Type;
        }
    }

    lJobMode                        = false;
}

/// <summary>
///    AVA <c>parmArgs</c> method.
/// </summary>
/// <param name="_parmValue">
///    <c>Args</c> as type
/// </param>
/// <returns>
///    <c>Args</c> as return value
/// </returns>
public Args parmArgs(Args _parmValue = frmArgs)
{
    frmArgs = _parmValue;

    return frmArgs;
}

